DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.start_life_activity(text,uuid,uuid)'::regprocedure) INTO definition; definition:=replace(definition,' j public.jobs; id uuid;',' j public.jobs; result_id uuid;'); definition:=replace(definition,'INTO id;','INTO result_id;'); definition:=replace(definition,'RETURN id;','RETURN result_id;'); EXECUTE definition; END $$;